"""Runtime support for vecDSL programs generated for Redis Open Source with the Query Engine, through redis-py. Generated by
vecDSL 7. Do not edit.

Every statement arrives as Redis command argument arrays built by the generator, identical in the Python, TypeScript and
Java programs; values travel as separate arguments or as PARAMS of a query, never inside a query string. Records are JSON
documents under the collection's key prefix. Writes read the affected documents under WATCH, compute the new documents and
commit them in one MULTI/EXEC, so a write is atomic and fails when another client changed a key in between. Replies are read
in RESP2 from one connection, without the client's reply callbacks.
"""

from __future__ import annotations

import json
import math
import os
import random as _random
import re
import struct
import time
from decimal import Decimal
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence
from urllib.parse import unquote, urlparse

SDK_PACKAGE = "redis"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_DIGITS = 6
_BATCH = 500
_PAGE = 1000
_TIMEOUT = 10.0
_SEPARATORS = set(" \t,./(){}[]:;~!@#$%^&*-=+|'`\"<>?")
_DEFAULT_STOPWORDS = ("a", "is", "the", "an", "and", "are", "as", "at", "be", "but", "by", "for", "if", "in", "into", "it", "no", "not",
                      "of", "on", "or", "such", "that", "their", "then", "there", "these", "they", "this", "to", "was", "will", "with")
_MARKER = re.compile(r"\{\{(and|or|fuzzy1|fuzzy2|fuzzy3|prefix|prefixlast|tags):([A-Za-z0-9_]+)\}\}")


class UnsupportedFeature(NotImplementedError):
    pass


class ConflictError(RuntimeError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

import redis  # noqa: E402
from redis.exceptions import ResponseError  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


# ---------------------------------------------------------------- values


def plain(value: float) -> str:
    """A number as text in one form for every host language: integers without a fraction, others in plain decimal notation."""
    if isinstance(value, bool):
        raise TypeError("a boolean is not a number")
    if float(value).is_integer() and abs(value) < 1e15:
        return str(int(value))
    text = format(Decimal(repr(float(value))), "f")
    return text.rstrip("0").rstrip(".") if "." in text else text


def dumps(value: Any) -> str:
    """Compact JSON with numbers written by plain(), so that the three runtimes send identical documents."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError("JSON has no infinite or NaN numbers")
        return plain(value)
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(str(key), ensure_ascii=False) + ":" + dumps(item) for key, item in value.items()) + "}"
    if isinstance(value, (list, tuple)):
        return "[" + ",".join(dumps(item) for item in value) + "]"
    raise TypeError(f"cannot write {type(value).__name__} as JSON")


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _decode(reply: Any) -> Any:
    if isinstance(reply, bytes):
        return reply.decode("utf-8", errors="replace")
    if isinstance(reply, list):
        return [_decode(item) for item in reply]
    if isinstance(reply, ResponseError):
        raise reply
    return reply


def _argument(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return plain(value)
    if isinstance(value, str):
        return value
    raise TypeError(f"a query parameter must be a string, number or boolean, not {type(value).__name__}")


def key_text(identifier: Any) -> str:
    if isinstance(identifier, bool) or identifier is None:
        raise ValueError(f"invalid record key {identifier!r}")
    return plain(identifier) if isinstance(identifier, (int, float)) else str(identifier)


def _bf16(number: float) -> bytes:
    bits = struct.unpack("<I", struct.pack("<f", number))[0]
    bits = (bits + 0x7FFF + ((bits >> 16) & 1)) >> 16
    return struct.pack("<H", bits & 0xFFFF)


def blob(vector: Sequence[float], kind: str) -> bytes:
    """A query vector as the little-endian bytes of the attribute's element type."""
    if kind == "BFLOAT16":
        return b"".join(_bf16(float(item)) for item in vector)
    codes = {"FLOAT32": "f", "FLOAT64": "d", "FLOAT16": "e", "INT8": "b", "UINT8": "B"}
    if kind not in codes:
        raise ValueError(f"unknown vector type {kind}")
    if kind in ("INT8", "UINT8"):
        items = [int(item) for item in vector]
    elif kind == "FLOAT16":
        items = [struct.unpack("<f", struct.pack("<f", float(item)))[0] for item in vector]
    else:
        items = [float(item) for item in vector]
    return struct.pack("<" + codes[kind] * len(items), *items)


def terms(text: str, stopwords: Sequence[str]) -> list[str]:
    """The terms of a text as the Query Engine tokenizes it (separators of src/toksep.h), without the index's stop words."""
    result, current = [], []
    for character in text:
        if character in _SEPARATORS:
            if current:
                result.append("".join(current))
                current = []
        else:
            current.append(character)
    if current:
        result.append("".join(current))
    stop = {word.lower() for word in stopwords}
    return [term for term in result if term.lower() not in stop]


# ---------------------------------------------------------------- connection


class Client:
    """One RESP2 connection; the user and password come from the environment, never from the URL."""

    def __init__(self, url: str, user_variable: str, password_variable: str) -> None:
        parsed = urlparse(url)
        if parsed.scheme not in ("redis", "rediss"):
            raise ValueError(f"expected a redis:// or rediss:// URL, got {url!r}")
        if parsed.password is not None:
            raise ValueError("the connection URL must not contain a password; set it in the environment")
        database = parsed.path.lstrip("/")
        if database not in ("", "0"):
            raise ValueError("the Query Engine indexes only database 0 (FT.CREATE answers 'Cannot create index on db != 0')")
        user = os.environ.get(user_variable) or (unquote(parsed.username) if parsed.username else None)
        options = {"host": parsed.hostname or "127.0.0.1", "port": parsed.port or 6379, "username": user,
                   "password": os.environ.get(password_variable), "socket_connect_timeout": _TIMEOUT,
                   "socket_timeout": 3 * _TIMEOUT, "protocol": 2}
        connection_class = redis.SSLConnection if parsed.scheme == "rediss" else redis.Connection
        self.connection = connection_class(**options)
        self.connection.connect()

    def call(self, *args: Any) -> Any:
        self.connection.send_command(*args)
        return self.connection.read_response()

    def close(self) -> None:
        self.connection.disconnect()


def connect(url: str, user_variable: str = "VECDSL_REDIS_USER", password_variable: str = "VECDSL_REDIS_PASSWORD") -> Client:
    return Client(url, user_variable, password_variable)


def _send(client: Client, args: Sequence[Any]) -> Any:
    return _decode(client.call(*args))


def command(client: Client, args: Sequence[Any], ignore: Sequence[str] = ()) -> Any:
    """One command; an error whose message contains one of the ignored phrases (lower case) returns None."""
    try:
        return _send(client, args)
    except ResponseError as error:
        if any(phrase in str(error).lower() for phrase in ignore):
            return None
        raise


def exists(client: Client, args: Sequence[Any]) -> bool:
    """Whether a lookup command (ACL GETUSER, for one) answers with a value rather than nil."""
    return _send(client, args) is not None


def durable(client: Client) -> None:
    """Waits until the local append-only file has fsynced every write so far (WAITAOF 1 0, at most ten seconds)."""
    local, _ = _send(client, ["WAITAOF", "1", "0", str(int(_TIMEOUT * 1000))])
    if local < 1:
        raise TimeoutError("WAITAOF: the append-only file was not fsynced within ten seconds")


# ---------------------------------------------------------------- documents


def _scan(client: Client, prefix: str) -> list[str]:
    pattern = re.sub(r"([*?\[\]\\])", r"\\\1", prefix) + "*"
    cursor, keys = "0", []
    while True:
        cursor, page = _send(client, ["SCAN", cursor, "MATCH", pattern, "COUNT", str(_PAGE)])
        keys.extend(page)
        if cursor == "0":
            return sorted(set(keys))


def _documents(client: Client, keys: Sequence[str]) -> list[dict[str, Any] | None]:
    if not keys:
        return []
    replies = _send(client, ["JSON.MGET", *keys, "$"])
    return [None if reply is None else json.loads(reply)[0] for reply in replies]


def _project(document: dict[str, Any], key: str, output: Sequence[str], vectors: Sequence[str], score: float | None) -> dict[str, Any]:
    hit: dict[str, Any] = {"id": document.get(key)}
    if score is not None:
        hit["score"] = score
    for name in [*output, *vectors]:
        hit[name] = document.get(name)
    return _value(hit)


class _Plan:
    """The documents of the keys a write touches, read under WATCH, changed in memory and committed in one MULTI/EXEC."""

    def __init__(self, client: Client) -> None:
        self.client = client
        self.docs: dict[str, dict[str, Any] | None] = {}
        self.ttl: dict[str, int] = {}
        self.expire: dict[str, int] = {}
        self.changed: list[str] = []

    def load(self, keys: Sequence[str]) -> None:
        fresh = [key for key in dict.fromkeys(keys) if key not in self.docs]
        if not fresh:
            return
        _send(self.client, ["WATCH", *fresh])
        for key, document in zip(fresh, _documents(self.client, fresh)):
            self.docs[key] = document
            self.ttl[key] = _send(self.client, ["PTTL", key])

    def put(self, key: str, document: dict[str, Any] | None) -> None:
        self.docs[key] = document
        if key not in self.changed:
            self.changed.append(key)

    def commit(self, wait: bool) -> None:
        if not self.changed:
            _send(self.client, ["UNWATCH"])
            return
        _send(self.client, ["MULTI"])
        try:
            for key in self.changed:
                document = self.docs[key]
                if document is None:
                    _send(self.client, ["DEL", key])
                    continue
                _send(self.client, ["JSON.SET", key, "$", dumps(document)])
                if key in self.expire:
                    _send(self.client, ["EXPIRE", key, str(self.expire[key])])
                elif self.ttl.get(key, -1) > 0:
                    _send(self.client, ["PEXPIRE", key, str(self.ttl[key])])
        except BaseException:
            _send(self.client, ["DISCARD"])
            raise
        if _send(self.client, ["EXEC"]) is None:
            raise ConflictError("another client changed a written key during the write (WATCH); nothing was written")
        if wait:
            durable(self.client)


def _record_document(record: dict[str, Any], key: str, vectors: dict[str, int], slices: dict[str, Any] | None) -> dict[str, Any]:
    if record.get(key) is None:
        raise ValueError(f"a record without its key field {key}")
    document = {name: item for name, item in record.items() if item is not None}
    for name, dim in vectors.items():
        if name in document and len(document[name]) != dim:
            raise ValueError(f"vector field {name} has {len(document[name])} dimensions, the index expects {dim}")
    document.update(slices or {})
    return document


def _write_into(plan: _Plan, prefix: str, key: str, records: Sequence[dict[str, Any]], policy: str, vectors: dict[str, int],
                slices: dict[str, Any] | None, ttl: int | None) -> int:
    documents = [_record_document(record, key, vectors, slices) for record in records]
    keys = [prefix + key_text(document[key]) for document in documents]
    if policy == "error" and len(set(keys)) != len(keys):
        raise ValueError("duplicate keys in one insert")
    plan.load(keys)
    written = 0
    for name, document in zip(keys, documents):
        if plan.docs.get(name) is not None and policy in ("error", "ignore"):
            if policy == "error":
                raise ValueError(f"duplicate key {name}")
            continue
        plan.put(name, document)
        if ttl is not None:
            plan.expire[name] = ttl
        written += 1
    return written


def write(client: Client, prefix: str, key: str, records: Sequence[dict[str, Any]], policy: str, counter: str,
          vectors: dict[str, int] | None = None, slices: dict[str, Any] | None = None, ttl: int | None = None,
          wait: bool = False, batch_size: int = _BATCH) -> dict[str, int]:
    """Writes records as documents in batches, each batch atomic; policy error, ignore or replace (update and upsert)."""
    total = 0
    for start in range(0, len(records), batch_size):
        plan = _Plan(client)
        total += _write_into(plan, prefix, key, records[start:start + batch_size], policy, vectors or {}, slices, ttl)
        plan.commit(wait)
    return {counter: total}


def _select(client: Client, prefix: str, ids: Sequence[Any] | None, search: dict[str, Any] | None) -> list[str]:
    if ids is not None:
        return list(dict.fromkeys(prefix + key_text(identifier) for identifier in ids))
    if search is not None:
        return _keys(client, search, None)
    return _scan(client, prefix)


def _change(document: dict[str, Any], change: dict[str, Any]) -> dict[str, Any]:
    result = dict(document)
    if change.get("replace") is not None:
        kept = {name: result[name] for name in change["replace"]["keep"] if name in result}
        result = kept
    for name, item in (change.get("set") or {}).items():
        if item is None:
            result.pop(name, None)
        else:
            result[name] = item
    for name, items in (change.get("append") or {}).items():
        result[name] = [*(result.get(name) or []), *items]
    for name, items in (change.get("remove") or {}).items():
        if result.get(name) is not None:
            result[name] = [item for item in result[name] if item not in items]
    for name in change.get("delete") or ():
        result.pop(name, None)
    return result


def _update_into(plan: _Plan, client: Client, prefix: str, key: str, change: dict[str, Any], ids: Sequence[Any] | None,
                 search: dict[str, Any] | None, records: Sequence[dict[str, Any]] | None) -> int:
    if records is not None:
        by_key = {prefix + key_text(record[key]): record for record in records}
        allowed = None if ids is None else {prefix + key_text(identifier) for identifier in ids}
        targets = [name for name in by_key if allowed is None or name in allowed]
    else:
        by_key, targets = {}, _select(client, prefix, ids, search)
    plan.load(targets)
    updated = 0
    for name in targets:
        document = plan.docs.get(name)
        if document is None:
            continue
        if records is not None:
            given = {field: item for field, item in by_key[name].items() if field != key}
            plan.put(name, _change(document, {**change, "set": given}))
        else:
            plan.put(name, _change(document, change))
        updated += 1
    return updated


def update(client: Client, prefix: str, key: str, ids: Sequence[Any] | None = None, search: dict[str, Any] | None = None,
           set: dict[str, Any] | None = None, append: dict[str, list[Any]] | None = None,  # noqa: A002
           remove: dict[str, list[Any]] | None = None, delete: Sequence[str] | None = None, replace: dict[str, Any] | None = None,
           records: Sequence[dict[str, Any]] | None = None, wait: bool = False) -> dict[str, int]:
    """Changes existing documents: set fields (None removes one), append to and remove from arrays, delete fields, replace."""
    plan = _Plan(client)
    change = {"set": set, "append": append, "remove": remove, "delete": delete, "replace": replace}
    count = _update_into(plan, client, prefix, key, change, ids, search, records)
    plan.commit(wait)
    return {"update_count": count}


def delete(client: Client, prefix: str, ids: Sequence[Any] | None = None, search: dict[str, Any] | None = None,
           limit: int | None = None, wait: bool = False) -> dict[str, int]:
    """Deletes documents by key, by a filter (in key order, at most limit) or all documents under the prefix."""
    if search is not None:
        keys = _keys(client, search, limit)
    else:
        keys = _select(client, prefix, ids, None)
    count = 0
    for start in range(0, len(keys), _PAGE):
        count += _send(client, ["DEL", *keys[start:start + _PAGE]])
    if wait:
        durable(client)
    return {"delete_count": count}


def transaction(client: Client, steps: Sequence[dict[str, Any]], wait: bool = False) -> list[Any]:
    """Writes by key of several statements in one MULTI/EXEC; each step sees the documents the earlier steps wrote."""
    plan = _Plan(client)
    results: list[Any] = []
    for step in steps:
        kind = step["op"]
        if kind == "write":
            count = _write_into(plan, step["prefix"], step["key"], step["records"], step["policy"], step.get("vectors") or {},
                                step.get("slices"), step.get("ttl"))
            results.append({step["counter"]: count})
        elif kind == "update":
            change = {name: step.get(name) for name in ("set", "append", "remove", "delete", "replace")}
            count = _update_into(plan, client, step["prefix"], step["key"], change, step.get("ids"), None, step.get("records"))
            results.append({"update_count": count})
        else:
            names = [step["prefix"] + key_text(identifier) for identifier in step["ids"]]
            plan.load(names)
            count = 0
            for name in dict.fromkeys(names):
                if plan.docs.get(name) is not None:
                    plan.put(name, None)
                    count += 1
            results.append({"delete_count": count})
    plan.commit(wait)
    return results


def truncate(client: Client, prefix: str) -> dict[str, int]:
    return delete(client, prefix)


def drop_collection(client: Client, index: str, prefix: str, if_exists: bool = False) -> None:
    """FT.DROPINDEX without DD, then every key under the prefix (DD deletes only the documents the index holds)."""
    if if_exists and index not in _send(client, ["FT._LIST"]):
        truncate(client, prefix)
        return
    _send(client, ["FT.DROPINDEX", index])
    truncate(client, prefix)


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, location: str, prefix: str, key: str, policy: str, counter: str, vectors: dict[str, int] | None = None,
                slices: dict[str, Any] | None = None, batch_size: int = _BATCH, wait: bool = False) -> dict[str, int]:
    return write(client, prefix, key, read_records(client, location), policy, counter, vectors, slices, None, wait, batch_size)


# ---------------------------------------------------------------- queries


def _expand(search: dict[str, Any]) -> list[Any]:
    """The command with text markers expanded into term parameters and PARAMS appended."""
    params = {name: _argument(item) for name, item in (search.get("params") or {}).items()}
    stopwords = search.get("stopwords")
    stopwords = _DEFAULT_STOPWORDS if stopwords is None else stopwords
    texts = search.get("texts") or {}

    def replace(match: re.Match[str]) -> str:
        mode, name = match.group(1), match.group(2)
        value = texts[name]
        found = [_argument(item) for item in value] if mode == "tags" else terms(str(value), stopwords)
        if not found:
            raise ValueError(f"the text {value!r} has no terms to search for")
        for index, term in enumerate(found):
            params[f"{name}_{index}"] = term
        names = [f"${name}_{index}" for index in range(len(found))]
        if mode.startswith("fuzzy"):
            marks = "%" * int(mode[-1])
            return " ".join(f"{marks}{item}{marks}" for item in names)
        if mode == "prefix":
            return " ".join(f"{item}*" for item in names)
        if mode == "prefixlast":
            names[-1] += "*"
        return (" | " if mode in ("or", "tags") else " ").join(names)

    args: list[Any] = [_MARKER.sub(replace, item) for item in search["command"]]
    for name, item in (search.get("vectors") or {}).items():
        params[name] = item
    if params:
        args.append("PARAMS")
        args.append(str(2 * len(params)))
        for name, item in params.items():
            args.extend((name, item))
    return args


def _query_vector(client: Client, search: dict[str, Any]) -> None:
    """Resolves the vector of a search: given, a stored record's, or the average of example records and vectors (recommend)."""
    lookup = search.get("lookup")
    if lookup is None:
        return
    positives = [*lookup.get("positive_vectors", [])]
    negatives = [*lookup.get("negative_vectors", [])]
    for ids, target in ((lookup.get("positive_ids", []), positives), (lookup.get("negative_ids", []), negatives)):
        names = [lookup["prefix"] + key_text(identifier) for identifier in ids]
        for name, document in zip(names, _documents(client, names)):
            if document is None or document.get(lookup["path"]) is None:
                raise ValueError(f"no vector {lookup['path']} stored under {name}")
            target.append(document[lookup["path"]])
    if not positives:
        raise ValueError("no positive example to search with")
    dim = len(positives[0])
    mean = [sum(vector[i] for vector in positives) / len(positives) for i in range(dim)]
    if negatives:
        negative = [sum(vector[i] for vector in negatives) / len(negatives) for i in range(dim)]
        mean = [2 * mean[i] - negative[i] for i in range(dim)]
    search.setdefault("vectors_raw", {})[lookup["param"]] = mean


def _similarity(distance: float, metric: str | None, native: bool) -> float:
    if metric is None or native:
        return distance
    if metric == "euclidean":
        return -math.sqrt(max(distance, 0.0))
    return 1.0 - distance


def _scored(client: Client, search: dict[str, Any]) -> tuple[list[tuple[str, float | None]], int]:
    """The keys and raw scores of a search, best first, and its total."""
    search = dict(search)
    _query_vector(client, search)
    raw = {**(search.get("vectors_raw") or {})}
    for name, item in (search.get("blobs") or {}).items():
        if name in (search.get("params") or {}) and name not in raw:
            raw[name] = search["params"][name]
    search["params"] = {name: item for name, item in (search.get("params") or {}).items() if name not in (search.get("blobs") or {})}
    search["vectors"] = {name: blob(raw[name], kind) for name, kind in (search.get("blobs") or {}).items()}
    reply = _send(client, _expand(search))
    form = search["reply"]
    if form == "hybrid":
        fields = dict(zip(reply[::2], reply[1::2]))
        rows = [dict(zip(item[::2], item[1::2])) for item in fields["results"]]
        return [(row["__key"], float(row["__score"])) for row in rows], int(fields["total_results"])
    total, rest = reply[0], reply[1:]
    if form == "scores":
        return [(rest[i], float(rest[i + 1])) for i in range(0, len(rest), 2)], total
    if form == "knn":
        return [(rest[i], float(dict(zip(rest[i + 1][::2], rest[i + 1][1::2]))[_SCORE])) for i in range(0, len(rest), 2)], total
    return [(row[row.index("__key") + 1], None) for row in rest], total


_SCORE = "vecdsl_score"


def _keys(client: Client, search: dict[str, Any], limit: int | None) -> list[str]:
    """Keys of the documents a filter matches, in key order: every page of an FT.AGGREGATE, or the first limit keys."""
    if limit is not None:
        page = dict(search, command=_paged(search["command"], 0, limit), reply="keys")
        return [name for name, _ in _scored(client, page)[0]]
    keys: list[str] = []
    while True:
        page = dict(search, command=_paged(search["command"], len(keys), _PAGE), reply="keys")
        found = [name for name, _ in _scored(client, page)[0]]
        keys.extend(found)
        if len(found) < _PAGE:
            return keys


def _paged(args: Sequence[str], offset: int, limit: int) -> list[str]:
    result = list(args)
    at = result.index("LIMIT")
    result[at + 1:at + 3] = [str(offset), str(limit)]
    return result


def _hits(client: Client, scored: Sequence[tuple[str, float | None]], key: str, output: Sequence[str], vectors: Sequence[str],
          metric: str | None, native: bool, low: float | None, high: float | None) -> list[dict[str, Any]]:
    hits = []
    for (name, score), document in zip(scored, _documents(client, [name for name, _ in scored])):
        if document is None:
            continue
        value = None if score is None else _similarity(score, metric, native)
        if value is not None and ((low is not None and value < low) or (high is not None and value > high)):
            continue
        hits.append(_project(document, key, output, vectors, value))
    return hits


def search(client: Client, command: Sequence[str], reply: str, key: str, output: Sequence[str],  # noqa: A002
           params: dict[str, Any] | None = None, texts: dict[str, Any] | None = None, stopwords: Sequence[str] | None = None,
           blobs: dict[str, str] | None = None, lookup: dict[str, Any] | None = None, vectors: Sequence[str] = (),
           metric: str | None = None, native: bool = False, low: float | None = None, high: float | None = None,
           total: dict[str, Any] | None = None) -> Any:
    """A search built by the generator: the hits (id, score, output fields, vector fields), or {hits, total} with total."""
    definition = {"command": command, "reply": reply, "params": params, "texts": texts, "stopwords": stopwords, "blobs": blobs,
                  "lookup": lookup}
    scored, _ = _scored(client, definition)
    hits = _hits(client, scored, key, output, vectors, metric, native, low, high)
    return hits if total is None else {"hits": hits, "total": count(client, **total)}


def scroll(client: Client, command: Sequence[str], key: str, output: Sequence[str], params: dict[str, Any] | None = None,  # noqa: A002
           texts: dict[str, Any] | None = None, stopwords: Sequence[str] | None = None, vectors: Sequence[str] = (),
           every: bool = False) -> list[dict[str, Any]]:
    """Documents in the order of an FT.AGGREGATE SORTBY: one page, or with every all pages from the command's offset."""
    definition = {"command": command, "reply": "keys", "params": params, "texts": texts, "stopwords": stopwords}
    if every:
        names = _keys(client, definition, None)
    else:
        names = [name for name, _ in _scored(client, definition)[0]]
    return _hits(client, [(name, None) for name in names], key, output, vectors, None, False, None, None)


def _order(identifier: Any) -> tuple[int, Any]:
    return (0, identifier) if isinstance(identifier, (int, float)) and not isinstance(identifier, bool) else (1, str(identifier))


def hybrid(client: Client, legs: Sequence[dict[str, Any]], fusion: str, key: str, output: Sequence[str], limit: int,
           offset: int = 0, k: int = 60, weights: Sequence[float] | None = None, vectors: Sequence[str] = (),
           low: float | None = None, high: float | None = None) -> list[dict[str, Any]]:
    """Legs searched one by one and fused as vecDSL defines rrf (sum of 1/(k + rank)), weighted and relative_score; ties by key."""
    weights = weights or [1.0] * len(legs)
    fused: dict[str, float] = {}
    documents: dict[str, dict[str, Any]] = {}
    for leg, weight in zip(legs, weights):
        definition = {name: leg.get(name) for name in ("command", "reply", "params", "texts", "stopwords", "blobs", "lookup")}
        scored, _ = _scored(client, definition)
        values = [(name, _similarity(score if score is not None else 0.0, leg.get("metric"), False)) for name, score in scored]
        if fusion == "relative_score" and values:
            least, most = min(value for _, value in values), max(value for _, value in values)
            values = [(name, 1.0 if most == least else (value - least) / (most - least)) for name, value in values]
        for rank, (name, value) in enumerate(values, start=1):
            part = 1.0 / (k + rank) if fusion == "rrf" else weight * value
            fused[name] = fused.get(name, 0.0) + part
    names = list(fused)
    for name, document in zip(names, _documents(client, names)):
        if document is not None:
            documents[name] = document
    ranked = sorted(documents, key=lambda name: (-fused[name], _order(documents[name].get(key))))
    hits = []
    for name in ranked:
        value = fused[name]
        if (low is not None and value < low) or (high is not None and value > high):
            continue
        hits.append(_project(documents[name], key, output, vectors, value))
    return hits[offset:offset + limit]


def count(client: Client, command: Sequence[str], params: dict[str, Any] | None = None,  # noqa: A002
          texts: dict[str, Any] | None = None, stopwords: Sequence[str] | None = None) -> int:
    """The total of an FT.SEARCH with LIMIT 0 0."""
    definition = {"command": command, "params": params, "texts": texts, "stopwords": stopwords}
    return int(_send(client, _expand(definition))[0])


def get(client: Client, prefix: str, key: str, ids: Sequence[Any], output: Sequence[str], vectors: Sequence[str] = (),
        slices: dict[str, Sequence[Any]] | None = None) -> list[dict[str, Any]]:
    """Documents by key, in the order of the ids; missing keys are skipped, and documents outside the slices (attribute -> values)."""
    names = [prefix + key_text(identifier) for identifier in ids]
    return [_project(document, key, output, vectors, None) for document in _documents(client, names) if document is not None
            and all(document.get(attribute) in values for attribute, values in (slices or {}).items())]


def sample(client: Client, prefix: str, key: str, size: int, output: Sequence[str], search: dict[str, Any] | None = None,
           first: bool = False) -> list[dict[str, Any]]:
    """first: the first records in key order; random: a uniform sample of the matching records (runs differ)."""
    keys = _keys(client, search, size if first else None) if search is not None else _scan(client, prefix)
    chosen = keys[:size] if first else _random.sample(keys, min(size, len(keys)))
    if first and search is None:
        documents = [document for document in _documents(client, keys) if document is not None]
        documents.sort(key=lambda document: _order(document.get(key)))
        return [_project(document, key, output, (), None) for document in documents[:size]]
    return [_project(document, key, output, (), None) for document in _documents(client, chosen) if document is not None]


def distance_matrix(client: Client, prefix: str, key: str, field: str, metric: str, size: int, limit: int,
                    search: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Each sampled record with its nearest neighbours among the sample (canonical similarity, computed in the runtime)."""
    keys = _keys(client, search, None) if search is not None else _scan(client, prefix)
    chosen = [document for document in _documents(client, _random.sample(keys, min(size, len(keys)))) if document and document.get(field)]
    pairs = []
    for left in chosen:
        scored = []
        for right in chosen:
            if right is left:
                continue
            u, v = left[field], right[field]
            if metric == "euclidean":
                value = -math.sqrt(sum((a - b) ** 2 for a, b in zip(u, v)))
            elif metric == "dot":
                value = sum(a * b for a, b in zip(u, v))
            else:
                norms = math.sqrt(sum(a * a for a in u)) * math.sqrt(sum(b * b for b in v))
                value = sum(a * b for a, b in zip(u, v)) / norms if norms else 0.0
            scored.append((value, right))
        scored.sort(key=lambda item: (-item[0], _order(item[1].get(key))))
        pairs.extend({"a": left.get(key), "b": right.get(key), "score": value} for value, right in scored[:limit])
    return _value(pairs)


# ---------------------------------------------------------------- operations


def _pairs(reply: Sequence[Any]) -> dict[str, Any]:
    return dict(zip(reply[::2], reply[1::2]))


def describe(client: Client, index: str, stats: bool = False, progress: bool = False) -> dict[str, Any]:
    """FT.INFO as {name, prefix, attributes} with count and indexing state on request."""
    info = _pairs(_send(client, ["FT.INFO", index]))
    definition = _pairs(info["index_definition"])
    attributes = []
    for attribute in info["attributes"]:
        fields = {}
        rest = list(attribute)
        while rest:
            name = rest.pop(0)
            if rest and name in ("identifier", "attribute", "type", "WEIGHT", "SEPARATOR", "algorithm", "data_type", "dim",
                                 "distance_metric", "M", "ef_construction"):
                fields[name.lower()] = rest.pop(0)
        attributes.append({"name": fields.get("attribute"), "path": fields.get("identifier"), "type": fields.get("type")})
    result: dict[str, Any] = {"name": info["index_name"], "prefix": definition.get("prefixes", [None])[0], "attributes": attributes}
    if stats:
        result["count"] = int(info["num_docs"])
    if progress:
        result["indexing"] = int(info["indexing"]) != 0
        result["percent_indexed"] = float(info["percent_indexed"])
    return _value(result)


def await_index(client: Client, index: str, timeout: float = 60.0) -> dict[str, Any]:
    """Polls FT.INFO until the background scan of existing keys has finished, at most timeout seconds."""
    deadline = time.monotonic() + timeout
    while True:
        info = _pairs(_send(client, ["FT.INFO", index]))
        if int(info["indexing"]) == 0:
            return {"index": index, "state": "ready", "percent_indexed": _value(float(info["percent_indexed"]))}
        if time.monotonic() > deadline:
            raise TimeoutError(f"index {index} was still indexing after {timeout} seconds")
        time.sleep(0.2)


def names(client: Client, kind: str, prefix: str | None = None, limit: int | None = None, database: str | None = None,
          index: str | None = None, attribute: str | None = None) -> list[str]:
    """collections and databases (from FT._LIST), aliases (FT.ALIASLIST), tag values of a slice attribute (FT.TAGVALS)."""
    if kind == "collections":
        found = [name for name in _send(client, ["FT._LIST"])
                 if (database is None and ":" not in name) or (database is not None and name.startswith(database + ":"))]
        found = [name.split(":", 1)[1] if database is not None else name for name in found]
    elif kind == "databases":
        found = sorted({name.split(":", 1)[0] for name in _send(client, ["FT._LIST"]) if ":" in name})
    elif kind == "aliases":
        found = _send(client, ["FT.ALIASLIST", index]) if index is not None else []
    elif kind == "indexes":
        found = [index] if index is not None else []
    else:
        found = _send(client, ["FT.TAGVALS", index, attribute])
    found = sorted(name for name in found if prefix is None or name.startswith(prefix))
    return found if limit is None else found[:limit]


def recreate(client: Client, index: str, create: Sequence[str]) -> None:
    """Drops the index without its documents and creates it again with its aliases; the new index scans the existing keys in the background."""
    aliases = _send(client, ["FT.ALIASLIST", index]) or []
    _send(client, ["FT.DROPINDEX", index])
    _send(client, create)
    for alias in aliases:
        command(client, ["FT.ALIASADD", alias, index], ["alias already exists"])


def rewrite(client: Client, prefix: str, rename: dict[str, str] | None = None, delete: Sequence[str] | None = None) -> dict[str, int]:
    """Renames or removes fields in every document under the prefix (an alter of the collection), in batches."""
    keys = _scan(client, prefix)
    changed = 0
    for start in range(0, len(keys), _BATCH):
        plan = _Plan(client)
        batch = keys[start:start + _BATCH]
        plan.load(batch)
        for name in batch:
            document = plan.docs.get(name)
            if document is None:
                continue
            updated = {(rename or {}).get(field, field): item for field, item in document.items() if field not in (delete or ())}
            if updated != document:
                plan.put(name, updated)
                changed += 1
        plan.commit(False)
    return {"update_count": changed}


def expire(client: Client, prefix: str, seconds: int) -> dict[str, int]:
    """EXPIRE on every key under the prefix (a collection ttl set by alter; later writes set it themselves)."""
    keys = _scan(client, prefix)
    return {"expire_count": sum(_send(client, ["EXPIRE", name, str(seconds)]) for name in keys)}


def copy_collection(client: Client, prefix: str, target: str, create: Sequence[str], move: bool = False,
                    drop: str | None = None) -> dict[str, int]:
    """Copies (COPY) or renames (RENAME) every key under the prefix to the target prefix, then creates the target's index."""
    keys = _scan(client, prefix)
    for name in keys:
        _send(client, ["RENAME" if move else "COPY", name, target + name[len(prefix):]])
    if drop is not None:
        _send(client, ["FT.DROPINDEX", drop])
    _send(client, create)
    return {"moved_count" if move else "copied_count": len(keys)}
